  const issuedInvoice = r2.value;

  const result = overdueInvoices([issuedInvoice], '2026-10-15');
  assert.equal(result.length, 0);
});

test('overdueInvoices excludes invoice on exact due date', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
