});

test('overdueInvoices includes invoice day after due date', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
