  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;

  const result = overdueInvoices([issuedInvoice], '2026-10-16');
  assert.equal(result.length, 1);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;

  const result = overdueInvoices([issuedInvoice], '2026-10-25');
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices with partially_paid invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;
  const r3 = recordPayment(issuedInvoice, { amount: 3000, date: '2026-10-02' });

  const result = overdueInvoices([r3.value], '2026-10-16');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 3050);
});

test('overdueInvoices does not mutate invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;
  const originalCopy = JSON.parse(JSON.stringify(issuedInvoice));

  overdueInvoices([issuedInvoice], '2026-10-16');
  assert.deepEqual(issuedInvoice, originalCopy);
});

test('overdueInvoices with multiple customers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const invoice1 = r1.value;
  const r2 = issueInvoice(invoice1, ['INV-2026-0001']);
