});

test('overdueInvoices maintains correct structure', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issuedInvoice = r2.value;

  const result = overdueInvoices([issuedInvoice], '2026-10-16');
  assert.equal(result.length, 1);
  const item = result[0];
  assert.equal(typeof item.number, 'string');
  assert.equal(typeof item.customerId, 'string');
  assert.equal(typeof item.dueDate, 'string');
  assert.equal(typeof item.daysOverdue, 'number');
